contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint cBalBefore = address(c).balance;
        uint testBalBefore = address(this).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        assert(
            (value <= cBalBefore && !reverted && address(this).balance == testBalBefore + value && address(c).balance == cBalBefore - value && depositsAfter == depositsBefore)
            ||
            (value > cBalBefore && reverted && address(this).balance == testBalBefore && address(c).balance == cBalBefore && depositsAfter == depositsBefore)
        );
    }

    receive() external payable {}
}

