        c = new SimpleWallet();
    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        uint cBalBefore = address(c).balance;
        uint testBalBefore = address(this).balance;
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        assertTrue((value <= cBalBefore && !reverted && address(this).balance == testBalBefore + value && address(c).balance == cBalBefore - value && depositsAfter == depositsBefore)
            ||
            (value > cBalBefore && reverted && address(this).balance == testBalBefore && address(c).balance == cBalBefore && depositsAfter == depositsBefore));
